import mongoose from "mongoose";

export const validateMongoId = (id) => {
    if (mongoose.Types.ObjectId.isValid(id)) {
        // Valid format, but it could still be a 12-byte string generated by chance
        if (new mongoose.Types.ObjectId(id).toString() === id) {
            return true; // Strictly a valid ObjectId
        }
    }
    return false; // Invalid
};

export const cleanMongoObject = (raw) => {
    const semi = raw.toObject();
    semi.id = raw._id;
    delete semi._id;
    delete semi.__v;
    delete semi.createdAt;
    delete semi.updatedAt;
    return semi;
}